import base64
import mimetypes
import os
from dataclasses import dataclass
from typing import Any, Dict, Optional

import requests


OPENAI_VISION_MODEL = os.getenv("OPENAI_VISION_MODEL", "gpt-4o-mini")
OPENAI_API_URL = os.getenv("OPENAI_API_URL", "https://api.openai.com/v1/chat/completions")


@dataclass
class VisionConfig:
    api_key: str
    model: str = OPENAI_VISION_MODEL
    api_url: str = OPENAI_API_URL
    timeout: int = 60


def load_config() -> VisionConfig:
    api_key = os.getenv("OPENAI_API_KEY", "")
    if not api_key:
        raise ValueError("OPENAI_API_KEY is required")
    return VisionConfig(
        api_key=api_key,
        model=os.getenv("OPENAI_VISION_MODEL", OPENAI_VISION_MODEL),
        api_url=os.getenv("OPENAI_API_URL", OPENAI_API_URL),
        timeout=int(os.getenv("OPENAI_TIMEOUT", "60")),
    )


def image_to_data_url(image_path: str) -> str:
    mime_type, _ = mimetypes.guess_type(image_path)
    if not mime_type:
        mime_type = "image/png"
    with open(image_path, "rb") as f:
        encoded = base64.b64encode(f.read()).decode("ascii")
    return f"data:{mime_type};base64,{encoded}"


def build_vision_payload(prompt: str, image_path: str, model: Optional[str] = None) -> Dict[str, Any]:
    return {
        "model": model or OPENAI_VISION_MODEL,
        "messages": [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt},
                    {"type": "image_url", "image_url": {"url": image_to_data_url(image_path)}},
                ],
            }
        ],
        "temperature": 0,
    }


def post_vision_request(prompt: str, image_path: str, config: Optional[VisionConfig] = None, model: Optional[str] = None) -> Dict[str, Any]:
    cfg = config or load_config()
    payload = build_vision_payload(prompt, image_path, model=model or cfg.model)
    response = requests.post(
        cfg.api_url,
        headers={
            "Authorization": f"Bearer {cfg.api_key}",
            "Content-Type": "application/json",
        },
        json=payload,
        timeout=cfg.timeout,
    )
    response.raise_for_status()
    return response.json()

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional


@dataclass
class ImageAnalysisRequest:
    image_path: str
    prompt: str
    mime_type: Optional[str] = None
    model: Optional[str] = None
    max_tokens: Optional[int] = None
    temperature: Optional[float] = None


@dataclass
class LabelItem:
    name: str
    confidence: Optional[float] = None
    score: Optional[float] = None
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass
class ImageSummaryResult:
    text: str
    raw: Optional[Dict[str, Any]] = None


@dataclass
class TextDetectionResult:
    text: str
    items: List[str] = field(default_factory=list)
    raw: Optional[Dict[str, Any]] = None


@dataclass
class SafetyResult:
    unsafe: bool
    categories: List[str] = field(default_factory=list)
    score: Optional[float] = None
    raw: Optional[Dict[str, Any]] = None


def normalize_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, (int, float, bool)):
        return str(value)
    return str(value).strip()


def normalize_label_item(value: Any) -> LabelItem:
    if isinstance(value, LabelItem):
        return value
    if isinstance(value, str):
        return LabelItem(name=value.strip())
    if not isinstance(value, dict):
        return LabelItem(name=normalize_text(value))
    metadata = dict(value)
    name = normalize_text(metadata.pop("name", metadata.pop("label", metadata.pop("text", ""))))
    confidence = metadata.pop("confidence", metadata.pop("score", None))
    return LabelItem(name=name, confidence=confidence, score=confidence, metadata=metadata)


def normalize_labels(value: Any) -> List[LabelItem]:
    if value is None:
        return []
    if isinstance(value, list):
        return [normalize_label_item(item) for item in value]
    return [normalize_label_item(value)]


def normalize_summary_response(value: Any) -> ImageSummaryResult:
    if isinstance(value, ImageSummaryResult):
        return value
    if isinstance(value, dict):
        text = normalize_text(value.get("text", value.get("summary", value.get("content", ""))))
        return ImageSummaryResult(text=text, raw=value)
    return ImageSummaryResult(text=normalize_text(value))


def normalize_text_detection_response(value: Any) -> TextDetectionResult:
    if isinstance(value, TextDetectionResult):
        return value
    if isinstance(value, dict):
        text = normalize_text(value.get("text", value.get("content", value.get("transcript", ""))))
        items = value.get("items", value.get("texts", []))
        if not isinstance(items, list):
            items = [items]
        return TextDetectionResult(text=text, items=[normalize_text(item) for item in items if normalize_text(item)], raw=value)
    text = normalize_text(value)
    return TextDetectionResult(text=text, items=[text] if text else [])


def normalize_safety_response(value: Any) -> SafetyResult:
    if isinstance(value, SafetyResult):
        return value
    if isinstance(value, dict):
        unsafe = bool(value.get("unsafe", value.get("flagged", False)))
        categories = value.get("categories", value.get("labels", []))
        if not isinstance(categories, list):
            categories = [categories]
        score = value.get("score", value.get("confidence"))
        return SafetyResult(unsafe=unsafe, categories=[normalize_text(category) for category in categories if normalize_text(category)], score=score, raw=value)
    return SafetyResult(unsafe=bool(value), raw={"value": value})

import base64
import json
import os
import urllib.request


OPENAI_API_URL = "https://api.openai.com/v1/chat/completions"
OPENAI_VISION_MODEL = os.getenv("OPENAI_VISION_MODEL", "gpt-4.1-mini")


def _image_to_data_url(image_path):
    with open(image_path, "rb") as f:
        encoded = base64.b64encode(f.read()).decode("ascii")
    mime_type = "image/jpeg"
    return f"data:{mime_type};base64,{encoded}"


def _extract_summary_text(payload):
    choices = payload.get("choices") or []
    if not choices:
        return ""
    message = choices[0].get("message") or {}
    text = message.get("content") or ""
    return text.strip()


def summarize_image_analysis(image_path, analysis_results=None, mime_type="image/jpeg"):
    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is required")

    analysis_text = ""
    if analysis_results is not None:
        if isinstance(analysis_results, str):
            analysis_text = analysis_results.strip()
        else:
            analysis_text = json.dumps(analysis_results, ensure_ascii=False, sort_keys=True)

    prompt = (
        "Summarize the visual analysis results for this image in 1-3 concise sentences. "
        "Focus on the most important objects, scene context, text, and any safety-relevant details."
    )
    if analysis_text:
        prompt = f"{prompt}\n\nAnalysis results:\n{analysis_text}"

    payload = {
        "model": OPENAI_VISION_MODEL,
        "messages": [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt},
                    {"type": "image_url", "image_url": {"url": _image_to_data_url(image_path), "detail": "low"}},
                ],
            }
        ],
        "max_tokens": 120,
        "temperature": 0.2,
    }
    request = urllib.request.Request(
        OPENAI_API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=60) as response:
        data = json.load(response)
    return _extract_summary_text(data)


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("usage: image_summary.py IMAGE_PATH [ANALYSIS_JSON_OR_TEXT]")
    image_path = sys.argv[1]
    analysis = sys.argv[2] if len(sys.argv) > 2 else None
    print(summarize_image_analysis(image_path, analysis))

